---@param uiMain_ table 
---@param switchTF_ UnityEngine.Transform
function IdolLive3D_UISwitchV2:__init( uiMain_, switchTF_, jumpBtn_Pos_, jumpBtn_Cam_ )

    self.uiMain = uiMain_
    self.baseJson = self.uiMain.baseJson
    self.switch = switchTF_
    self.uiKey = Live3D_UIKey.switchPanel

    self.jumpBtn_Pos = jumpBtn_Pos_
    self.jumpBtn_Cam = jumpBtn_Cam_
    self.stageJumpBtn_Pos_Env = IdolLive3D_UIStageJumpBtn_Pos.New( self.jumpBtn_Pos, self )
    self.stageJumpBtn_Cam_Env = IdolLive3D_UIStageJumpBtn_Cam.New( self.jumpBtn_Cam, self )

    -- !!! todo: 初始状态 需要定制:
    KTool.SetActive( self.switch.gameObject, true )
    CfUtils.SetCanvasGroupAlpha( self.switch.gameObject, 0.0 )
    CfUtils.SetCanvasGroupInteractable( self.switch.gameObject, false )


    self.smoothShow = IdolLive3D_UISmoothShowEnt.New( self.switch.gameObject, true, false, false, 0.9, 3 )
    self.isActive = false   -- 是否点击可起效
    ---
    self.isCustomShow = true -- 定制脚本: isShow    -- !!! 也许可以分发下去 而不是自己持有
    self.isCustomGray = false -- 定制脚本: isGray   -- !!! 也许可以分发下去 而不是自己持有
    
    ------- 
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        -- 允许 客制代码 手动隐藏 本按钮:
        [IdolLive3D_States.EventSetUICustomShow] = function( uiKey_, isShow_, fadeTime_, isEffectImmediately_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            self.isCustomShow = (isShow_==true)
            if isEffectImmediately_ == true then 
                self:Show(true, fadeTime_)
            end
        end,

        -- 允许 客制代码 手动置灰 本按钮:
        [IdolLive3D_States.EventSetUICustomGray] = function( uiKey_, isGray_, isEffectImmediately_ )
            if uiKey_ ~= self.uiKey then 
                return
            end
            self.isCustomGray = (isGray_==true)
            if isEffectImmediately_ == true then 
                self:SetGray(true)
            end
        end,
    })    
end




-- 需手动调用 Delete()
function IdolLive3D_UISwitchV2:__delete()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end

    if isNotNull(self.stageJumpBtn_Pos_Env) then 
        self.stageJumpBtn_Pos_Env:Delete()
    end
    if isNotNull(self.stageJumpBtn_Cam_Env) then 
        self.stageJumpBtn_Cam_Env:Delete()
    end
end



function IdolLive3D_UISwitchV2:SelfUpdate()
    self.smoothShow:SelfUpdate()
end

----------------------------------------------------------


function IdolLive3D_UISwitchV2:SetActive( isActive_ )
    self.isActive = (isActive_==true)
end

function IdolLive3D_UISwitchV2:IsActive()
    return (self.isActive==true)
end


---@param isShow_ boolean 
---@param fadeInTime_ number | nil
function IdolLive3D_UISwitchV2:Show( isShow_, fadeTime_ )
    --printError(" show-1-:" .. tostring(isShow_) .. ", -2-:" .. tostring(self.isCustomShow) .. ", time = " .. tostring(fadeInTime_))
    local doShow = (isShow_==true and self.isCustomShow==true)
    if isNull(fadeTime_) then 
        fadeTime_ = doShow and switchBtn_fadeInTime or switchBtn_fadeOutTime
    end 
    self.smoothShow:SetShowOrHide( isShow_==true and self.isCustomShow==true, fadeTime_ )
end



---@param isGray_ boolean @ 允许重复设置
function IdolLive3D_UISwitchV2:SetGray( isGray_ )
    --printError("gray = " .. tostring(isGray_))
    local doGray = (isGray_ == true or self.isCustomGray == true )
    self.stageJumpBtn_Pos_Env:SetGray( doGray )
    self.stageJumpBtn_Cam_Env:SetGray( doGray )
end



return IdolLive3D_UISwitchV2
